async function send(value: string | null) {
  if (!value) return;

  // ❌ TypeScript error after await — value is string | null again
  await flush();
  console.log(value.toUpperCase()); // error: value possibly null

  // ✅ Capture in const before awaiting
  const safeValue = value; // type: string
  await flush();
  console.log(safeValue.toUpperCase()); // fine
}

// Starves I/O — 'file read' never logs
function recurse() {
  process.nextTick(recurse);
}
